</main>
@if($mode === 'pending')<script>
const input=document.getElementById('videoInput'), preview=document.getElementById('preview'), player=document.getElementById('previewVideo'), loading=document.getElementById('loading'), send=document.getElementById('send'), replace=document.getElementById('replace'), error=document.getElementById('localError'), form=document.getElementById('evidenceForm'); let objectUrl=null, selectedVideoFile=null;
const formatSize=b=>b<1048576?(b/1024).toFixed(1)+' KB':(b/1048576).toFixed(1)+' MB'; const formatDuration=s=>`00:${s.toFixed(2).padStart(5,'0')}`;
function clearPreview(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;selectedVideoFile=null;player.removeAttribute('src');preview.classList.add('hidden');send.disabled=true;error.classList.add('hidden');}
function showError(message){error.textContent=message;error.classList.remove('hidden');send.disabled=false;replace.disabled=false;input.disabled=false;document.getElementById('picker').classList.remove('hidden');document.getElementById('sending').classList.add('hidden');}
input.addEventListener('change',()=>{const file=input.files[0];clearPreview();if(!file)return;selectedVideoFile=file;loading.classList.remove('hidden');objectUrl=URL.createObjectURL(selectedVideoFile);player.src=objectUrl;player.onloadedmetadata=()=>{loading.classList.add('hidden');preview.classList.remove('hidden');document.getElementById('duration').textContent=formatDuration(player.duration);document.getElementById('size').textContent=formatSize(selectedVideoFile.size);if(!Number.isFinite(player.duration)||player.duration>10){error.textContent=`Este vídeo possui ${player.duration.toFixed(2)} segundos. O limite é de 10 segundos.`;error.classList.remove('hidden');send.disabled=true;return;}send.disabled=false;};player.onerror=()=>{loading.classList.add('hidden');preview.classList.remove('hidden');error.textContent='Não foi possível ler os metadados deste vídeo. Escolha outro arquivo.';error.classList.remove('hidden');};});
replace.addEventListener('click',()=>{clearPreview();input.value='';input.click();});form.addEventListener('submit',async event=>{event.preventDefault();if(!(selectedVideoFile instanceof File)){showError('Selecione um vídeo antes de enviar.');return;}if(@json(config('app.debug')))console.debug('Video upload',{isFile:selectedVideoFile instanceof File,name:selectedVideoFile.name,size:selectedVideoFile.size,type:selectedVideoFile.type});send.disabled=true;replace.disabled=true;input.disabled=true;document.getElementById('picker').classList.add('hidden');document.getElementById('sending').classList.remove('hidden');const data=new FormData();data.append('_token',form.querySelector('[name=_token]').value);data.append('video',selectedVideoFile,selectedVideoFile.name);try{const response=await fetch(form.action,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':form.querySelector('[name=_token]').value},body:data,credentials:'same-origin'});if(response.status===422){const body=await response.json();showError(Object.values(body.errors||{}).flat().join(' ')||body.message||'Não foi possível enviar o vídeo.');return;}if(!response.ok)throw new Error(`HTTP ${response.status}`);window.location.assign(response.url);}catch(exception){console.error('Falha no envio do vídeo',exception);showError('Não foi possível enviar o vídeo. Tente novamente.');}});window.addEventListener('pagehide',clearPreview);
</script>@endif
</html>
